B.a5i=s(["Your first look at CMY and color","\u521d\u8b58 CMY \u8207\u8272\u5f69\u89c0\u5bdf"],t.s)
B.aeQ=s(["The Science of Light & Color","\u5149\u8207\u8272\u5f69\u79d1\u5b78"],t.s)
B.agX=s(["Visible light, reflection and primary colors","\u53ef\u898b\u5149\u3001\u53cd\u5c04\u8207\u4e09\u539f\u8272"],t.s)
B.adn=s(["Applied Color Perception","\u8272\u5f69\u8996\u89ba\u61c9\u7528"],t.s)
B.anp=s(["Contrast, area and lighting","\u5c0d\u6bd4\u3001\u9762\u7a4d\u8207\u7167\u660e"],t.s)
B.a8P=s(["How Oxidative Color Works","\u6c27\u5316\u67d3\u5291\u7684\u539f\u7406"],t.s)
B.a1n=s(["First agent, developer and color development","\u7b2c\u4e00\u5291\u3001\u7b2c\u4e8c\u5291\u8207\u986f\u8272"],t.s)
B.amg=s(["Lightness & Undertones","\u660e\u5ea6\u8207\u5e95\u8272"],t.s)
B.Zv=s(["Levels, lightening and residual pigment","\u8272\u5ea6\u3001\u812b\u8272\u8207\u6b98\u7559\u8272\u7d20"],t.s)
B.a5g=s(["Hair Growth & Structure","\u982d\u9aee\u751f\u9577\u8207\u7d50\u69cb"],t.s)
